mapper.select:
SELECT id, room_id, applicant_id, applicant_name, applicant_phone, reservation_date,
       start_minute, end_minute, reason, attendee_count, note, status, request_id,
       handled_by, handled_at, result_reason, created_at, updated_at
FROM reservation
WHERE room_id = #{roomId}
  AND reservation_date = #{date}
  AND start_minute < #{endMinute}
  AND end_minute > #{startMinute}
  AND status IN

    #{status}

FOR UPDATE
